<!-- wp:paragraph {"align":"center","style":{"color":{"text":"#2c3239"},"typography":{"fontSize":"16px","lineHeight":"2"},"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center has-text-color" style="color:#2c3239;font-size:16px;line-height:2;margin-top:28px;margin-bottom:24px">お手元にあると早いものを下に挙げましたが、<span class="lw-br on_500px"></span>ひとつも無くてもご相談いただけます。</p>
<!-- /wp:paragraph -->
